func (suite *handlersSuite) TestComputeProvenWordPairs_UnassignedRecentWindow() {
	// Arrange — no assignment: scope is the most-recent _provenScopeSize (15)
	// attempts. The older pair falls outside the window and is not proven.
	ctx := suite.KAContext()
	attempts := make([]*models.LanglitChallengeAttempt, 0, 17)
	for i := range 15 {
		attempts = append(attempts, &models.LanglitChallengeAttempt{
			UserKAID: "kaid_test", LanglitChallengeID: "recent_" + strconv.Itoa(i),
			Performance:   []int{1},
			ChallengeType: models.LanglitChallengeTypeFrequentlyConfusedWords,
			WordPair:      "accept|except",
		})
	}
	for i := range 2 {
		attempts = append(attempts, &models.LanglitChallengeAttempt{
			UserKAID: "kaid_test", LanglitChallengeID: "old_" + strconv.Itoa(i),
			Performance:   []int{1},
			ChallengeType: models.LanglitChallengeTypeFrequentlyConfusedWords,
			WordPair:      "affect|effect",
		})
	}

	// Act
	proven, err := langlit.ComputeProvenWordPairs(
		ctx, attempts, "", models.LanglitChallengeTypeFrequentlyConfusedWords,
	)

	// Assert — only the in-window pair is proven.
	suite.Require().NoError(err)
	suite.Require().Equal([]string{"accept|except"}, proven)
}

func (suite *handlersSuite) TestComputeProvenWordPairs_PartiallyCorrectDoesNotCount() {
	// Arrange — two attempts on the same pair, each with one slot wrong.
	// An attempt only counts when every correction slot is right.
	ctx := suite.KAContext()
	assignmentID := "assign_1"
	attempts := []*models.LanglitChallengeAttempt{
		{
			UserKAID: "kaid_test", LanglitChallengeID: "c1",
			Performance: []int{1, 0}, AssignmentID: &assignmentID,
			ChallengeType: models.LanglitChallengeTypeFrequentlyConfusedWords,
			WordPair:      "accept|except",
		},
		{
			UserKAID: "kaid_test", LanglitChallengeID: "c2",
			Performance: []int{1, 0}, AssignmentID: &assignmentID,
			ChallengeType: models.LanglitChallengeTypeFrequentlyConfusedWords,
			WordPair:      "accept|except",
		},
	}

	// Act
	proven, err := langlit.ComputeProvenWordPairs(
		ctx, attempts, assignmentID, models.LanglitChallengeTypeFrequentlyConfusedWords,
	)

	// Assert
	suite.Require().NoError(err)
	suite.Require().Empty(proven)
}

func (suite *handlersSuite) TestComputeProvenWordPairs_MissingChallenge_SkipsAttempt() {
	// Arrange — a cold attempt whose challenge no longer exists. The backfill
	// must skip it rather than erroring out the whole computation.
	ctx := suite.KAContext()
	userKAID := "kaid_test"
	assignmentID := "assign_1"

	attempt := &models.LanglitChallengeAttempt{
		UserKAID:           userKAID,
		LanglitChallengeID: "deleted_challenge",
		Performance:        []int{1},
		AssignmentID:       &assignmentID,
	}
	attempt.Key = models.MakeLanglitChallengeAttemptKey(userKAID, "deleted_challenge")
	_, err := ctx.Datastore().Put(ctx, attempt.Key, attempt)
	suite.Require().NoError(err)

	// Act
	proven, err := langlit.ComputeProvenWordPairs(
		ctx,
		[]*models.LanglitChallengeAttempt{attempt},
		assignmentID,
		models.LanglitChallengeTypeFrequentlyConfusedWords,
	)

	// Assert — no error, and the orphaned attempt contributes nothing.
	suite.Require().NoError(err)
	suite.Require().Empty(proven)
}

